package ec.espe.facturacion.adapters.out;
import javax.sql.DataSource; import java.sql.*; import java.io.PrintWriter; import java.util.logging.Logger;
public class DriverManagerDataSource implements DataSource {private final String url,user,password;public DriverManagerDataSource(String u,String n,String p){url=u;user=n;password=p;}public Connection getConnection()throws SQLException{return DriverManager.getConnection(url,user,password);}public Connection getConnection(String u,String p)throws SQLException{return DriverManager.getConnection(url,u,p);}public PrintWriter getLogWriter(){return null;}public void setLogWriter(PrintWriter p){}public void setLoginTimeout(int s)throws SQLException{DriverManager.setLoginTimeout(s);}public int getLoginTimeout()throws SQLException{return DriverManager.getLoginTimeout();}public Logger getParentLogger(){return Logger.getLogger("global");}public <T>T unwrap(Class<T> c)throws SQLException{throw new SQLException("No soportado");}public boolean isWrapperFor(Class<?> c){return false;}}
